create function public.import_my_corporate_travellers(p_corporate_account_id uuid,p_rows jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_actor uuid:=auth.uid();v_row jsonb;v_index integer:=0;v_name text;v_dob date;v_nationality text;v_passport text;v_expiry date;v_notes text;v_ids uuid[]:='{}';v_id uuid;v_seen text[]:='{}';
begin if v_actor is null then raise exception 'Authentication required';end if;if not exists(select 1 from public.corporate_portal_members m join public.corporate_accounts a on a.id=m.corporate_account_id where m.user_id=v_actor and m.corporate_account_id=p_corporate_account_id and m.status='active' and m.can_request and a.archived_at is null)then raise exception 'Active company request access required';end if;if jsonb_typeof(p_rows)<>'array'or jsonb_array_length(p_rows)not between 1 and 100 then raise exception 'Import must contain 1 to 100 traveller rows';end if;
 for v_row in select value from jsonb_array_elements(p_rows)loop v_index:=v_index+1;v_name:=btrim(coalesce(v_row->>'full_name',''));v_nationality:=nullif(btrim(coalesce(v_row->>'nationality','')),'');v_passport:=nullif(regexp_replace(upper(btrim(coalesce(v_row->>'passport_number',''))),'[^A-Z0-9]','','g'),'');v_notes:=nullif(btrim(coalesce(v_row->>'notes','')),'');if char_length(v_name)<2 then raise exception 'Row %: full_name is required',v_index;end if;if char_length(v_name)>180 then raise exception 'Row %: full_name is too long',v_index;end if;if v_notes is not null and char_length(v_notes)>500 then raise exception 'Row %: notes exceed 500 characters',v_index;end if;begin v_dob:=case when nullif(btrim(coalesce(v_row->>'date_of_birth','')),'')is null then null else(v_row->>'date_of_birth')::date end;v_expiry:=case when nullif(btrim(coalesce(v_row->>'passport_expiry','')),'')is null then null else(v_row->>'passport_expiry')::date end;exception when others then raise exception 'Row %: dates must use YYYY-MM-DD',v_index;end;if v_dob is not null and v_dob>=current_date then raise exception 'Row %: date_of_birth must be in the past',v_index;end if;if v_expiry is not null and v_expiry<current_date then raise exception 'Row %: passport is expired',v_index;end if;if v_passport is not null and v_passport=any(v_seen)then raise exception 'Row %: duplicate passport within this file',v_index;end if;if v_passport is not null and exists(select 1 from public.travellers where corporate_account_id=p_corporate_account_id and active and archived_at is null and regexp_replace(upper(coalesce(passport_number,'')),'[^A-Z0-9]','','g')=v_passport)then raise exception 'Row %: passport already exists for this company',v_index;end if;if v_passport is not null then v_seen:=array_append(v_seen,v_passport);end if;end loop;
 v_index:=0;for v_row in select value from jsonb_array_elements(p_rows)loop v_index:=v_index+1;v_name:=btrim(v_row->>'full_name');v_nationality:=nullif(btrim(coalesce(v_row->>'nationality','')),'');v_passport:=nullif(regexp_replace(upper(btrim(coalesce(v_row->>'passport_number',''))),'[^A-Z0-9]','','g'),'');v_notes:=nullif(btrim(coalesce(v_row->>'notes','')),'');v_dob:=case when nullif(btrim(coalesce(v_row->>'date_of_birth','')),'')is null then null else(v_row->>'date_of_birth')::date end;v_expiry:=case when nullif(btrim(coalesce(v_row->>'passport_expiry','')),'')is null then null else(v_row->>'passport_expiry')::date end;insert into public.travellers(corporate_account_id,full_name,date_of_birth,nationality,passport_number,passport_expiry,notes,created_by)values(p_corporate_account_id,v_name,v_dob,v_nationality,v_passport,v_expiry,v_notes,v_actor)returning id into v_id;v_ids:=array_append(v_ids,v_id);end loop;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'corporate_travellers_csv_imported','corporate_account',p_corporate_account_id,jsonb_build_object('row_count',cardinality(v_ids),'traveller_ids',to_jsonb(v_ids)));return jsonb_build_object('ok',true,'imported_count',cardinality(v_ids),'traveller_ids',to_jsonb(v_ids));end$$;
revoke execute on function public.import_my_corporate_travellers(uuid,jsonb) from public,anon;grant execute on function public.import_my_corporate_travellers(uuid,jsonb) to authenticated;
